import React from 'react';
import '../styles/GlobalStyles.css';

const HomePage = () => {
  return (
    <div className="container">
      <h1>Welcome to the Virtual Event Platform</h1>
      <p style={{ fontSize: '1.2rem', lineHeight: '1.6' }}>
        Experience a seamless virtual event experience. Join live sessions, interact through chat, and manage your events easily.
      </p>
      <button className="btn">Explore Events</button>
    </div>
  );
};

export default HomePage;
